#pragma once
#include "s2_run.hpp"
#include "s2_metadata.hpp"
#include <iostream>
#include <cctype>
namespace s2 {
struct Options{std::string command;std::map<std::string,std::string> values;bool engineering=false;const std::string& get(const std::string& key)const{auto it=values.find(key);if(it==values.end())throw std::invalid_argument("missing --"+key);return it->second;}};
inline Options parse(const std::vector<std::string>& args){if(args.empty())throw std::invalid_argument("prepare/run/describe/selftest required");Options o;o.command=args[0];std::set<std::string> allowed,required;if(o.command=="prepare"){allowed={"timestamps","source-sha","output","seed","case","profile","scale"};required={"timestamps","source-sha","output","seed","case","profile"};}else if(o.command=="run"){allowed={"cache","cache-sha","method","output","batch-id","pair-id","round","role"};required=allowed;}else if(o.command!="describe"&&o.command!="selftest")throw std::invalid_argument("unknown S2 command");for(std::size_t j=1;j<args.size();++j){auto s=args[j];if(s=="--engineering"&&o.command=="run"){if(o.engineering)throw std::invalid_argument("duplicate flag");o.engineering=true;continue;}if(s.size()<3||s.substr(0,2)!="--"||!allowed.count(s.substr(2))||j+1>=args.size())throw std::invalid_argument("unknown/protected/missing option "+s);auto key=s.substr(2);auto value=args[++j];if(value.empty()||value.substr(0,2)=="--"||!o.values.emplace(key,value).second)throw std::invalid_argument("duplicate/empty option "+key);}for(auto& key:required)o.get(key);if(o.command=="prepare"){auto number=udriver::strict_u64(o.get("seed"));if(number>UINT_MAX)throw std::invalid_argument("seed overflow");validate_case(o.get("case"));validate_profile(o.get("profile"),unsigned(number));if(o.values.count("scale")&&(o.get("profile")!="engineering"||(o.get("scale")!="full"&&o.get("scale")!="mini")))throw std::invalid_argument("scale is engineering mini/full only");}if(o.command=="run"){if(o.get("round")!="AB"&&o.get("round")!="BA")throw std::invalid_argument("round AB/BA");if(o.get("role")!="A"&&o.get("role")!="B")throw std::invalid_argument("role A/B");for(auto key:{"batch-id","pair-id"})for(unsigned char c:o.get(key))if(!(std::isalnum(c)||c=='_'||c=='-'||c=='.'))throw std::invalid_argument("identity must be filename-safe ASCII");if(o.get("method")!="M_LIST"&&o.get("method")!="M_EVENT_16"&&o.get("method")!="R6"&&o.get("method")!="TLX")throw std::invalid_argument("unknown method");}return o;}
inline void fresh(const std::filesystem::path& p){if(std::filesystem::exists(p))throw std::runtime_error("immutable output exists");std::filesystem::create_directories(p);}
inline std::string counter_values(const Counters& c){return c.promotions+","+c.scheduled_demotions+","+c.cleanup_demotions+","+c.total_demotions+","+c.peak_tree_buckets+","+c.final_tree_buckets+","+c.candidate_max+","+c.nodes_allocated;}
inline constexpr const char* counter_columns="promotions,scheduled_demotions,cleanup_demotions,total_demotions,peak_tree_buckets,final_tree_buckets,candidate_max,nodes_allocated";
inline void write_result(const Options& o,const Bundle& b,const Result& r,const std::filesystem::path& dir){std::ofstream raw(dir/"raw.csv");raw<<"schema,batch_id,pair_id,round,role,mode,method,case_id,profile,seed,N,U,horizon,cache_sha,source_sha,protocol_sha,trace_hash,initial_sha,final_sha,queries,returned,query_hash,API_calls,build_ns,online_ns,total_ns,destroy_ns,verified,owner_current_after_destroy,owner_live_after_destroy,owner_peak,"<<counter_columns<<",process_mask_start,cpu_start,group_start,process_mask_end,cpu_end,group_end,pool_current,pool_peak,buckets_current,buckets_peak,tree_current,tree_peak,manager_current,manager_peak,binary_sha,source_bundle_sha\n";
 raw<<"S2.raw.v1,"<<o.get("batch-id")<<','<<o.get("pair-id")<<','<<o.get("round")<<','<<o.get("role")<<','<<mode()<<','<<o.get("method")<<','<<b.request.workload<<','<<b.request.month.substr(3)<<','<<b.request.seed<<','<<b.request.initial<<','<<b.request.units<<','<<b.request.units/b.request.initial<<','<<o.get("cache-sha")<<','<<source_sha<<','<<b.request.protocol_sha<<','<<b.whole.hash<<','<<record_sha(b.whole.initial)<<','<<record_sha(b.whole.final)<<','<<b.whole.queries<<','<<r.returned<<','<<r.query_hash<<','<<r.API_calls<<','<<r.build_ns<<','<<r.online_ns<<','<<r.total_ns<<','<<r.destroy_ns<<",true,"<<owner_value(r.owner_current_after_destroy)<<','<<owner_value(r.owner_live_after_destroy)<<','<<owner_value(r.owner_peak)<<','<<counter_values(r.counters)<<','<<r.start.process_mask<<','<<r.start.cpu<<','<<r.start.group<<','<<r.end.process_mask<<','<<r.end.cpu<<','<<r.end.group;for(unsigned k=0;k<4;++k)raw<<','<<r.account_current[k]<<','<<r.account_peak[k];raw<<','<<binary_sha()<<','<<source_bundle_sha<<'\n';raw.close();if(!raw)throw std::runtime_error("raw write");
 std::ofstream phases(dir/"phases.csv");phases<<"phase,name,begin,end,queries,returned,online_ns\n";for(std::size_t j=0;j<r.phases.size();++j){const auto& p=r.phases[j];phases<<j<<','<<p.name<<','<<p.begin<<','<<p.end<<','<<p.queries<<','<<p.returned<<','<<p.online_ns<<'\n';}phases.close();if(!phases)throw std::runtime_error("phases write");
 if(std::string(mode())=="resource"){std::ofstream snaps(dir/"snapshots.csv");snaps<<"unit,phase_boundary,whole_current,whole_peak,whole_live,pool_current,pool_peak,buckets_current,buckets_peak,tree_current,tree_peak,manager_current,manager_peak,"<<counter_columns<<'\n';for(const auto& s:r.snapshots){snaps<<s.unit<<','<<(s.phase_boundary?"true":"false")<<','<<s.whole_current<<','<<s.whole_peak<<','<<s.whole_live;for(unsigned k=0;k<4;++k)snaps<<','<<s.current[k]<<','<<s.peak[k];snaps<<','<<counter_values(s.counters)<<'\n';}snaps.close();if(!snaps)throw std::runtime_error("snapshots write");}
 std::ofstream receipt(dir/"receipt.json");receipt<<"{\"schema\":\"S2.run.v1\",\"batch_id\":"<<quote(o.get("batch-id"))<<",\"pair_id\":"<<quote(o.get("pair-id"))<<",\"round\":"<<quote(o.get("round"))<<",\"role\":"<<quote(o.get("role"))<<",\"mode\":"<<quote(mode())<<",\"method\":"<<quote(o.get("method"))<<",\"case_id\":"<<quote(b.request.workload)<<",\"profile\":"<<quote(b.request.month.substr(3))<<",\"seed\":"<<b.request.seed<<",\"N\":"<<b.request.initial<<",\"U\":"<<b.request.units<<",\"horizon\":"<<b.request.units/b.request.initial<<",\"cache_sha\":"<<quote(o.get("cache-sha"))<<",\"source_sha\":"<<quote(source_sha)<<",\"protocol_sha\":"<<quote(b.request.protocol_sha)<<",\"trace_hash\":"<<b.whole.hash<<",\"initial_sha\":"<<quote(record_sha(b.whole.initial))<<",\"final_sha\":"<<quote(record_sha(b.whole.final))<<",\"queries\":"<<b.whole.queries<<",\"returned\":"<<r.returned<<",\"query_hash\":"<<r.query_hash<<",\"API_calls\":"<<r.API_calls<<",\"verified\":true,\"engineering_only\":"<<(o.engineering?"true":"false")<<",\"owner_current_after_destroy\":"<<owner_json(r.owner_current_after_destroy)<<",\"owner_live_after_destroy\":"<<owner_json(r.owner_live_after_destroy)<<",\"raw_sha\":"<<quote(s1::sha_file(dir/"raw.csv"))<<",\"phases_sha\":"<<quote(s1::sha_file(dir/"phases.csv"));if(std::string(mode())=="resource")receipt<<",\"snapshots_sha\":"<<quote(s1::sha_file(dir/"snapshots.csv"));receipt<<",\"binary_sha\":"<<quote(binary_sha())<<",\"source_bundle_sha\":"<<quote(source_bundle_sha)<<"}\n";receipt.close();if(!receipt)throw std::runtime_error("receipt write");}
inline int execute(const Options& o){if(o.command=="describe"){std::cout<<"{\"schema\":\"S2.describe.v1\",\"mode\":"<<quote(mode())<<",\"methods\":[\"M_LIST\",\"M_EVENT_16\",\"R6\",\"TLX\"],\"protocol_sha\":"<<quote(protocol_sha)<<",\"source_sha\":"<<quote(source_sha)<<",\"binary_sha\":"<<quote(binary_sha())<<",\"source_bundle_sha\":"<<quote(source_bundle_sha)<<"}\n";return 0;}s1::require_sha(protocol_path(),protocol_sha);
 if(o.command=="prepare"){auto out=std::filesystem::u8path(o.get("output"));if(std::filesystem::exists(out))throw std::runtime_error("immutable prepare output exists");auto source=load_timestamps(std::filesystem::u8path(o.get("timestamps")),o.get("source-sha"));auto profile=o.get("profile");auto n=profile=="engineering"&&(!o.values.count("scale")||o.get("scale")=="mini")?768:262144;auto longest=generate(std::move(source),o.get("case"),unsigned(udriver::strict_u64(o.get("seed"))),profile,n,protocol_sha);longest.request.data=o.get("timestamps");validate_bundle(longest);fresh(out);auto h4=out/"h4";fresh(h4);write_cache(h4/"cache.bin",longest);auto longest_sha=s1::sha_file(h4/"cache.bin");write_meta(h4/"cache.meta.json",longest,longest_sha,longest_sha);for(std::size_t h:{1,2}){auto b=prefix(longest,n*h);validate_bundle(b);auto dir=out/("h"+std::to_string(h));fresh(dir);write_cache(dir/"cache.bin",b);auto hash=s1::sha_file(dir/"cache.bin");write_meta(dir/"cache.meta.json",b,hash,longest_sha);}std::cout<<"{\"schema\":\"S2.prepare.v1\",\"longest_cache_sha\":"<<quote(longest_sha)<<",\"prefixes\":[1,2,4]}\n";return 0;}
 if(o.command=="run"){auto cache=std::filesystem::u8path(o.get("cache"));s1::require_sha(cache,o.get("cache-sha"));auto verified=verify_cache(cache,o.get("cache-sha"),o.engineering);const auto& b=verified.bundle;if((b.request.month=="S2:engineering")!=o.engineering)throw std::invalid_argument("engineering flag/profile mismatch");auto dir=std::filesystem::u8path(o.get("output"));if(std::filesystem::exists(dir))throw std::runtime_error("immutable run output exists");auto result=run(b,o.get("method"),!o.engineering,false);reverify_cache(verified);s1::require_sha(cache,o.get("cache-sha"));s1::require_sha(protocol_path(),protocol_sha);fresh(dir);write_result(o,b,result,dir);std::cout<<"{\"schema\":\"S2.run.v1\",\"verified\":true,\"mode\":"<<quote(mode())<<"}\n";return 0;}
 if(o.command=="selftest"){std::vector<Record> src;for(std::uint64_t j=1;j<=5000;++j)src.push_back({j/5*domain.stride+j,j});for(auto id:{"L01","L02","L03"}){auto b=generate(src,id,102001,"engineering",768,protocol_sha);for(auto method:{"M_LIST","M_EVENT_16","R6","TLX"})if(!run(b,method,false,true).verified)throw std::runtime_error("selftest");}std::cout<<"{\"schema\":\"S2.selftest.v1\",\"verified\":true,\"engineering_only\":true}\n";return 0;}throw std::logic_error("command dispatch");}
}
